using Xunit;
using HakutaiKagami.Core.Contracts;
namespace HakutaiKagami.Tests;
public sealed class HistoricalHouseholdTests
{
    static readonly EntityId Retainer=new("person:takeda-nobushige"),Lord=new("person:shingen");
    static SetupScenario Scenario()=>NewGameWorld.Scenario(HistoricalHouseholdCatalog.Id);
    static ContractWorld New()=>NewGameWorld.Create(Scenario(),[],Retainer.Value,20261022,NewGameWorld.CompactPersonalAuthority,HistoricalHouseholdCatalog.Id);
    static void At(WorldSession s,long t)=>NewGameWorldTests.At(s,t);
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
    [Fact] public void RealPriorWesternProfileKeepsExactFivePersonHash(){var bytes=File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","pre-household-start-west-v2.json"));var p=ContractJson.Read<NewCampaignProfile>(bytes);Assert.Equal(HistoricalStartCatalog.Western,p.HistoricalCatalog);Assert.Equal(5,p.Setup.People.Length);Assert.Equal("2c13b3e1bc0caf550f595fa25be2b13ac7263d6005c9f0eac0e881844c709639",ContractJson.CanonicalHash(NewCampaignStore.Build(p)));}
    [Fact] public void NewEditionAddsRetainerWithoutChangingFiveHeadsOrCastles(){var before=NewGameWorld.Scenario(HistoricalStartCatalog.Western);var after=Scenario();Assert.Equal(6,after.People.Length);Assert.Equal(ContractJson.Write(before.Factions),ContractJson.Write(after.Factions));Assert.Equal(ContractJson.Write(before.Castles),ContractJson.Write(after.Castles));Assert.Equal(ContractJson.Write(before.People),ContractJson.Write(after.People.Where(p=>p.Id!=Retainer.Value).ToArray()));Assert.Equal("武田信繁",after.People.Single(p=>p.Id==Retainer.Value).Name);}
    [Fact] public void RetainerKnowsInitialMembershipAndLordButReceivesNoArmyRights(){var w=New();var view=NewGameService.View(w);Assert.Equal(new EntityId("org:takeda"),view.House);Assert.Equal(Lord,view.Principal);Assert.Equal("家臣・随行",view.Role);Assert.True(NewGameService.BoundAt(w,Lord,0,0));Assert.Empty(w.Units);Assert.Empty(w.ResourceLots);Assert.DoesNotContain(w.Offices,o=>o.Subject==Retainer);Assert.DoesNotContain(w.LandRights,o=>o.Subject==Retainer);Assert.All(w.Grants.Where(g=>g.Agent==Retainer),g=>Assert.All(g.Actions,a=>Assert.True(a is ActionKind.Move or ActionKind.Inspect)));}
    [Fact] public void ExistingWorkDeliveryKeepsSealedBodyAndBindingOrder(){var s=new WorldSession(New());var i=NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:household-work");Assert.Equal(Lord,i.Actor);Assert.Equal(Retainer,i.Executor);Assert.Equal(TaskKind.BindingOrder,i.Kind);Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);At(s,1);Assert.Contains(s.GetActorView(Retainer).Messages,m=>m.KnownBody==null);Assert.DoesNotContain(s.GetActorView(Retainer).Messages,m=>m.KnownBody!=null);Open(s);Assert.DoesNotContain(s.DiagnosticSnapshot().Tasks,t=>t.Agreement==AgreementPhase.AwaitingAssent);At(s,8);Assert.Contains(s.DiagnosticSnapshot().EffectLedger,e=>e.Result=="completed");}
    [Fact] public void ExistingReleaseWaitsForPhysicalReport(){var s=new WorldSession(New());Assert.Equal(ResultCode.Accepted,s.Submit(NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:household-work"),s.Revision).Code);var c=NewGameService.View(s.DiagnosticSnapshot()).Cases.Single();Assert.Equal(ResultCode.Accepted,s.DecideService(new(new("request:household-leave"),CareerAction.RequestRelease,c.Case),Retainer,s.Revision).Code);At(s,2);Assert.Contains(s.DiagnosticSnapshot().Service!.Events,e=>e.Kind==CareerEventKind.ReleaseWaiting);Open(s);At(s,12);Open(s);Assert.Contains(s.DiagnosticSnapshot().Service!.Events,e=>e.Kind==CareerEventKind.Released);Assert.Null(NewGameService.View(s.DiagnosticSnapshot()).House);}
    [Fact] public void HouseholdCopiesCannotRewritePublishedEdition(){var c=HistoricalHouseholdCatalog.Edition;c.People[0]=c.People[0] with{Name="bad"};Assert.Equal("武田信繁",HistoricalHouseholdCatalog.Edition.People[0].Name);var s=Scenario();s.People[^1]=s.People[^1] with{Lord="person:nobunaga"};Assert.Throws<InvalidDataException>(()=>NewGameWorld.Create(s,[],Retainer.Value,historicalCatalog:HistoricalHouseholdCatalog.Id));}
    [Fact] public void SourceAndLordMustBelongToDeclaredEdition(){var c=HistoricalHouseholdCatalog.Edition;c.People[0]=c.People[0] with{SourceIds=["missing"]};Assert.Throws<InvalidDataException>(()=>HistoricalHouseholdCatalog.Validate(c));c=HistoricalHouseholdCatalog.Edition;c.People[0]=c.People[0] with{Lord=new("person:nobunaga")};Assert.Throws<InvalidDataException>(()=>HistoricalHouseholdCatalog.Validate(c));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(5)][InlineData(8)] public void SameRetainerWorkAndReportFutureSurvivesSave(int at){var initial=New();var s=new WorldSession(initial);Assert.Equal(ResultCode.Accepted,s.Submit(NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:household-save"),s.Revision).Code);if(at>0){At(s,1);Open(s);At(s,at);}s.SetPaused(true);var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"household-"+Guid.NewGuid().ToString("N")),initial.Definitions);store.Save(s,"manual",initial.WorldId,new(0,1));var host=new WorldSessionHost(new(New()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("manual"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));foreach(var x in new[]{s,host.Current}){if(at==0){At(x,1);Open(x);}At(x,12);Open(x);}Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));}
}
